package main

import (
	"strings"
	"testing"
)

// --- Helper functions ---

// assertStringContains checks that s contains substr
func assertStringContains(t *testing.T, s, substr string) {
	// TODO: add t.Helper() call
	t.Helper()
	if !strings.Contains(s, substr) {
		t.Errorf("expected %q to contain %q", s, substr)
	}
}

// assertLen checks that a slice has the expected length
func assertLen(t *testing.T, got, want int) {
	// TODO: add t.Helper() call
	if got != want {
		t.Errorf("length: got %d, want %d", got, want)
	}
}

// --- Function under test ---

func splitCSV(line string) []string {
	return strings.Split(line, ",")
}

// --- Tests using helpers ---

func TestSplitCSV(t *testing.T) {
	result := splitCSV("go,is,awesome")

	assertLen(t, len(result), 3)
	assertStringContains(t, result[0], "go")
	assertStringContains(t, result[2], "awesome")
}

func main() {
	t := &testing.T{}
	TestSplitCSV(t)
}
